{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-provider-status",
  "version": "0.1.5",
  "type": "module",
  "description": "OpenCode TUI plugin — shows AI provider usage/quota status in the session sidebar using public TUI slots.",
  "exports": {
    ".": {
      "import": "./tui.tsx",
      "config": {
        "title": "Provider Status",
        "interval_ms": 60000,
        "builtin": [
          "openai",
          "anthropic"
        ]
      }
    },
    "./tui": {
      "import": "./tui.tsx",
      "config": {
        "title": "Provider Status",
        "interval_ms": 60000,
        "builtin": [
          "openai",
          "anthropic"
        ]
      }
    }
  },
  "files": [
    "tui.tsx",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "opencode": ">=1.3.13",
    "node": ">=22"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "provider",
    "usage",
    "quota",
    "status",
    "custom-endpoint"
  ],
  "license": "MIT",
  "author": "Jinchao Wang",
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "check": "tsc --noEmit",
    "prepublishOnly": "npm run check"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.14.25",
    "@opentui/core": "^0.1.95",
    "@opentui/solid": "^0.1.95",
    "solid-js": "^1.9.10"
  },
  "devDependencies": {
    "@types/node": "^22.13.9",
    "typescript": "^5.8.2"
  }
}
